annual_div = df.groupby('Year').agg({'Dividends': 'sum', 'Close': 'last'}).reset_index()
annual_div['Yield'] = annual_div['Dividends'] / annual_div['Close'] * 100
annual_div = annual_div[annual_div['Dividends'] > 0]

# Stock splits
splits = df[df['Stock Splits'] > 0][['Date', 'Stock Splits', 'Close']].copy()
splits['DateStr'] = splits['Date'].dt.strftime('%Y-%m-%d')

# Annual returns for distribution
yearly_ret = df.groupby('Year').agg({'Close': ['first', 'last']}).reset_index()
yearly_ret.columns = ['Year', 'Open', 'Close']
yearly_ret['Return'] = (yearly_ret['Close'] / yearly_ret['Open']) - 1
pos_years = yearly_ret[yearly_ret['Return'] > 0]
neg_years = yearly_ret[yearly_ret['Return'] <= 0]

# Sharpe-like ratio (using 0% risk-free for simplicity, as is common in historical analysis)
sharpe = df['Daily_Return'].mean() / df['Daily_Return'].std() * np.sqrt(252)

